            [
                'id' => 56,
                'group' => 'home',
                'key' => 'about_desc',
                'value' => '{"fa":"\\u06af\\u0631\\u0648\\u0647 Stone Commerce \\u0628\\u0627 \\u0628\\u06cc\\u0634 \\u0627\\u0632 \\u06f2\\u06f5 \\u0633\\u0627\\u0644 \\u062a\\u062c\\u0631\\u0628\\u0647 \\u062f\\u0631 \\u0627\\u0633\\u062a\\u062e\\u0631\\u0627\\u062c\\u060c \\u0641\\u0631\\u0622\\u0648\\u0631\\u06cc \\u0648 \\u0635\\u0627\\u062f\\u0631\\u0627\\u062a \\u0633\\u0646\\u06af\\u200c\\u0647\\u0627\\u06cc \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u06cc\\u0631\\u0627\\u0646\\u060c \\u0627\\u0632 \\u062c\\u0645\\u0644\\u0647 \\u062a\\u0631\\u0627\\u0648\\u0631\\u062a\\u0646\\u060c \\u0645\\u0631\\u0645\\u0631\\u06cc\\u062a \\u0648 \\u06af\\u0631\\u0627\\u0646\\u06cc\\u062a\\u060c \\u06cc\\u06a9\\u06cc \\u0627\\u0632 \\u0645\\u0639\\u062a\\u0628\\u0631\\u062a\\u0631\\u06cc\\u0646 \\u062a\\u0623\\u0645\\u06cc\\u0646\\u200c\\u06a9\\u0646\\u0646\\u062f\\u06af\\u0627\\u0646 \\u0633\\u0646\\u06af \\u062f\\u0631 \\u0645\\u0646\\u0637\\u0642\\u0647 \\u0627\\u0633\\u062a.","en":"Stone Commerce, with over 25 years of experience in extracting, processing and exporting Iranian natural stones including travertine, marble and granite, is one of the most reputable stone suppliers in the region.","ar":"\\u0645\\u062c\\u0645\\u0648\\u0639\\u0629 Stone Commerce\\u060c \\u0628\\u062e\\u0628\\u0631\\u0629 \\u062a\\u0632\\u064a\\u062f \\u0639\\u0646 25 \\u0639\\u0627\\u0645\\u064b\\u0627 \\u0641\\u064a \\u0627\\u0633\\u062a\\u062e\\u0631\\u0627\\u062c \\u0648\\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0648\\u062a\\u0635\\u062f\\u064a\\u0631 \\u0627\\u0644\\u0623\\u062d\\u062c\\u0627\\u0631 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0639\\u064a\\u0629 \\u0627\\u0644\\u0625\\u064a\\u0631\\u0627\\u0646\\u064a\\u0629 \\u0628\\u0645\\u0627 \\u0641\\u064a \\u0630\\u0644\\u0643 \\u0627\\u0644\\u062a\\u0631\\u0627\\u06a4\\u0631\\u062a\\u064a\\u0646 \\u0648\\u0627\\u0644\\u0631\\u062e\\u0627\\u0645 \\u0648\\u0627\\u0644\\u062c\\u0631\\u0627\\u0646\\u064a\\u062a.","hi":"Stone Commerce, 25 \\u0938\\u0947 \\u0905\\u0927\\u093f\\u0915 \\u0935\\u0930\\u094d\\u0937\\u094b\\u0902 \\u0915\\u0947 \\u0905\\u0928\\u0941\\u092d\\u0935 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0908\\u0930\\u093e\\u0928\\u0940 \\u092a\\u094d\\u0930\\u093e\\u0915\\u0943\\u0924\\u093f\\u0915 \\u092a\\u0924\\u094d\\u0925\\u0930\\u094b\\u0902 \\u0915\\u0947 \\u0928\\u093f\\u0937\\u094d\\u0915\\u0930\\u094d\\u0937\\u0923, \\u092a\\u094d\\u0930\\u0938\\u0902\\u0938\\u094d\\u0915\\u0930\\u0923 \\u0914\\u0930 \\u0928\\u093f\\u0930\\u094d\\u092f\\u093e\\u0924 \\u092e\\u0947\\u0902\\u0964","it":"Stone Commerce, con oltre 25 anni di esperienza nell\'estrazione, lavorazione ed esportazione di pietre naturali iraniane.","zh":"Stone Commerce\\u62e5\\u6709\\u8d85\\u8fc725\\u5e74\\u5728\\u4f0a\\u6717\\u5929\\u7136\\u77f3\\u6750\\u5f00\\u91c7\\u3001\\u52a0\\u5de5\\u548c\\u51fa\\u53e3\\u65b9\\u9762\\u7684\\u7ecf\\u9a8c,\\u5305\\u62ec\\u6d1e\\u77f3\\u3001\\u5927\\u7406\\u77f3\\u548c\\u82b1\\u5c97\\u5ca9,\\u662f\\u8be5\\u5730\\u533a\\u6700\\u53d7\\u4fe1\\u8d56\\u7684\\u77f3\\u6750\\u4f9b\\u5e94\\u5546\\u4e4b\\u4e00\\u3002","tr":"Stone Commerce, traverten, mermer ve granit dahil olmak \\u00fczere \\u0130ran do\\u011fal ta\\u015flar\\u0131n\\u0131n \\u00e7\\u0131kar\\u0131lmas\\u0131, i\\u015flenmesi ve ihracat\\u0131nda 25 y\\u0131l\\u0131 a\\u015fk\\u0131n deneyime sahip olup, b\\u00f6lgenin en g\\u00fcvenilir ta\\u015f tedarik\\u00e7ilerinden biridir."}',
